using NaughtyAttributes;
using UnityEngine;
using UnityEngine.UI;

namespace Astrea;

public class MouseOverButtons : ZoomableInstance
{
	[Header("ButtonDescription")]
	[SerializeField]
	private bool disableButtonDescriptionData;

	[SerializeField]
	[HideIf("disableButtonDescriptionData")]
	private bool externalButtonDescriptionData;

	[SerializeField]
	[HideIf("hideButtonDescriptionData")]
	protected ButtonDescriptionData buttonDescriptionData;

	[Header("Action Description Panel Positioning")]
	[SerializeField]
	protected bool positionOverride;

	[SerializeField]
	[ShowIf("positionOverride")]
	protected TransformPositionOverride[] transformPositionOverrides;

	[Header("Dice Bag Discard Pools")]
	[SerializeField]
	private bool disableInteractionDuringNonBattleState;

	[Header("Button Component")]
	[SerializeField]
	private bool getButtonOnParents;

	private Button button;

	public bool DisableButtonDescriptionData => disableButtonDescriptionData;

	private bool hideButtonDescriptionData
	{
		get
		{
			if (!disableButtonDescriptionData)
			{
				return externalButtonDescriptionData;
			}
			return true;
		}
	}

	public ButtonDescriptionData ButtonDescriptionData => buttonDescriptionData;

	public Button Button => button;

	public void SetDisableButtonDescriptionData(bool value)
	{
		disableButtonDescriptionData = value;
	}

	public bool IsButtonClickable()
	{
		if (button == null)
		{
			return false;
		}
		if (hideButtonDescriptionData)
		{
			return button.interactable;
		}
		if (button.interactable)
		{
			return buttonDescriptionData.IsButtonClickable();
		}
		return false;
	}

	public void ClickButton()
	{
		if (button != null && IsButtonClickable())
		{
			button.onClick.Invoke();
			OnMouseExit();
		}
	}

	public void SetButtonDescriptionData(ButtonDescriptionData buttonDescriptionData)
	{
		this.buttonDescriptionData = buttonDescriptionData;
	}

	private void Start()
	{
		if (getButtonOnParents)
		{
			button = GetComponentInParent<Button>();
		}
		else
		{
			button = GetComponent<Button>();
		}
		ResetScale();
	}

	public void ResetButton()
	{
		ResetScale();
	}

	public override void OnMouseOver()
	{
		if (!disableInteractionDuringNonBattleState || !ReferenceSingleton<GameStateManager>.Instance.CurrentGameStateIsNonBattleState())
		{
			if (!hideButtonDescriptionData && buttonDescriptionData != null)
			{
				buttonDescriptionData.OnMouseOver();
			}
			base.OnMouseOver();
		}
	}

	public override void InitializeActionDescriptionPanel()
	{
		if (positionOverride)
		{
			actionDescriptionPanel.OverridePositions(transformPositionOverrides);
		}
		actionDescriptionPanel.InitializeButtonDescription(buttonDescriptionData);
	}
}
